  "implementation": "def solve(case):
    segments = case.get('segments')
    if segments is None or not isinstance(segments, list):
        raise ValueError("Missing or invalid 'segments'")
    budget = case.get('budget')
    if budget is None or not isinstance(budget, int):
        raise ValueError("Missing or invalid 'budget'")
    n = len(segments)
    names = []
    importances = []
    mins = []
    caps = []
    for i, seg in enumerate(segments):
        if not isinstance(seg, dict):
            raise ValueError(f"Segment {i} is not a dict")
        name = seg.get('name')
        if not isinstance(name, str):
            raise ValueError(f"Segment {i} missing or invalid 'name'")
        imp = seg.get('importance')
        if not isinstance(imp, int):
            raise ValueError(f"Segment {i} missing or invalid 'importance'")
        minv = seg.get('minimum')
        if not isinstance(minv, int):
            raise ValueError(f"Segment {i} missing or invalid 'minimum'")
        cap = seg.get('capacity')
        if not isinstance(cap, int):
            raise ValueError(f"Segment {i} missing or invalid 'capacity'")
        if minv < 0 or cap < 0 or minv > cap:
            raise ValueError(f"Segment {i} invalid min/capacity")
        names.append(name)
        importances.append(imp)
        mins.append(minv)
        caps.append(cap)
    total_min = sum(mins)
    total_max = sum(caps)
    if budget < total_min or budget > total_max:
        raise ValueError(f"Budget {budget} out of range [{total_min}, {total_max}]")
    allocations = mins[:]
    total_alloc = total_min
    while total_alloc < budget:
        best_idx = -1
        best_priority = -1.0
        for i in range(n):
            if allocations[i] < caps[i]:
                next_pos = allocations[i] + 1
                priority = importances[i] / next_pos
                if priority > best_priority:
                    best_priority = priority
                    best_idx = i
                elif priority == best_priority and best_idx == -1:
                    best_idx = i
        if best_idx == -1:
            break
        allocations[best_idx] += 1
        total_alloc += 1
    by_name = {names[i]: allocations[i] for i in range(n)}
    return {
        "allocations": allocations,
        "by_name": by_name,
        "total": sum(allocations)
    }"
}
